import { formatDate as formatDateSDK } from '@dynatrace-sdk/units';

/**
 * Formats the date with the default configuration
 * @internal
 */
export function _formatDate(value: number | Date) {
  const valueAsDate = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(valueAsDate.getTime())) {
    return '';
  }
  const omitSeconds =
    valueAsDate.getSeconds() === 0 && valueAsDate.getMilliseconds() === 0;
  return formatDateSDK(valueAsDate, {
    day: 'numeric',
    month: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: omitSeconds ? undefined : 'numeric',
  });
}
